-- Migration 0016: fold edition tags into song keys.
--
-- Migration 0012 keyed a song on its exact lowercased title, so "Heroes -
-- 2017 Remaster" and "Heroes" were two songs. Song keys now take a remaster,
-- "single version" or "radio edit" tag off the title (src/song-title.ts).
-- This rekeys every track and renumbers the songs that moved, as the daily
-- sweep (syncAllSongs in src/play-numbers.ts) would. Generated from it; the
-- tests check the two agree.

INSERT INTO track_songs (track_id, song)
     SELECT t.track_id, COALESCE((CASE WHEN lower(t.name) GLOB '?* - [0-9][0-9][0-9][0-9] digital remaster' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 24), ' ') WHEN lower(t.name) GLOB '?* ([0-9][0-9][0-9][0-9] digital remaster)' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 24), ' ') WHEN lower(t.name) GLOB '?* [[][0-9][0-9][0-9][0-9] digital remaster[]]' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 24), ' ') WHEN lower(t.name) GLOB '?* - digital remaster' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 19), ' ') WHEN lower(t.name) GLOB '?* (digital remaster)' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 19), ' ') WHEN lower(t.name) GLOB '?* [[]digital remaster[]]' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 19), ' ') WHEN lower(t.name) GLOB '?* - digitally remastered' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 23), ' ') WHEN lower(t.name) GLOB '?* (digitally remastered)' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 23), ' ') WHEN lower(t.name) GLOB '?* [[]digitally remastered[]]' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 23), ' ') WHEN lower(t.name) GLOB '?* - [0-9][0-9][0-9][0-9] remastered version' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 26), ' ') WHEN lower(t.name) GLOB '?* ([0-9][0-9][0-9][0-9] remastered version)' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 26), ' ') WHEN lower(t.name) GLOB '?* [[][0-9][0-9][0-9][0-9] remastered version[]]' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 26), ' ') WHEN lower(t.name) GLOB '?* - remastered [0-9][0-9][0-9][0-9] version' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 26), ' ') WHEN lower(t.name) GLOB '?* (remastered [0-9][0-9][0-9][0-9] version)' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 26), ' ') WHEN lower(t.name) GLOB '?* [[]remastered [0-9][0-9][0-9][0-9] version[]]' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 26), ' ') WHEN lower(t.name) GLOB '?* - remastered version' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 21), ' ') WHEN lower(t.name) GLOB '?* (remastered version)' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 21), ' ') WHEN lower(t.name) GLOB '?* [[]remastered version[]]' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 21), ' ') WHEN lower(t.name) GLOB '?* - remastered [0-9][0-9][0-9][0-9]' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 18), ' ') WHEN lower(t.name) GLOB '?* (remastered [0-9][0-9][0-9][0-9])' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 18), ' ') WHEN lower(t.name) GLOB '?* [[]remastered [0-9][0-9][0-9][0-9][]]' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 18), ' ') WHEN lower(t.name) GLOB '?* - [0-9][0-9][0-9][0-9] remastered' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 18), ' ') WHEN lower(t.name) GLOB '?* ([0-9][0-9][0-9][0-9] remastered)' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 18), ' ') WHEN lower(t.name) GLOB '?* [[][0-9][0-9][0-9][0-9] remastered[]]' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 18), ' ') WHEN lower(t.name) GLOB '?* - [0-9][0-9][0-9][0-9] remaster' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 16), ' ') WHEN lower(t.name) GLOB '?* ([0-9][0-9][0-9][0-9] remaster)' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 16), ' ') WHEN lower(t.name) GLOB '?* [[][0-9][0-9][0-9][0-9] remaster[]]' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 16), ' ') WHEN lower(t.name) GLOB '?* - remastered' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 13), ' ') WHEN lower(t.name) GLOB '?* (remastered)' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 13), ' ') WHEN lower(t.name) GLOB '?* [[]remastered[]]' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 13), ' ') WHEN lower(t.name) GLOB '?* - remaster' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 11), ' ') WHEN lower(t.name) GLOB '?* (remaster)' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 11), ' ') WHEN lower(t.name) GLOB '?* [[]remaster[]]' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 11), ' ') WHEN lower(t.name) GLOB '?* - single version' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 17), ' ') WHEN lower(t.name) GLOB '?* (single version)' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 17), ' ') WHEN lower(t.name) GLOB '?* [[]single version[]]' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 17), ' ') WHEN lower(t.name) GLOB '?* - radio edit' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 13), ' ') WHEN lower(t.name) GLOB '?* (radio edit)' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 13), ' ') WHEN lower(t.name) GLOB '?* [[]radio edit[]]' THEN rtrim(substr(lower(t.name), 1, length(lower(t.name)) - 13), ' ') ELSE lower(t.name) END) || char(31) || lower((SELECT a.name FROM track_artists ta JOIN artists a ON a.artist_id = ta.artist_id
     WHERE ta.track_id = t.track_id AND ta.position = 0 ORDER BY a.artist_id LIMIT 1)), char(30) || t.track_id) FROM tracks t WHERE true
     ON CONFLICT(track_id) DO UPDATE
        SET song = excluded.song, previous = COALESCE(track_songs.previous, track_songs.song), dirty = 1
      WHERE track_songs.song IS NOT excluded.song;

INSERT INTO play_numbers (played_at_ms, track_id, song, n)
       SELECT p.played_at_ms, p.track_id, ts.song,
              ROW_NUMBER() OVER (PARTITION BY ts.song ORDER BY p.played_at_ms, p.track_id)
         FROM track_songs ts JOIN plays p ON p.track_id = ts.track_id
        WHERE ts.song IN (SELECT song FROM track_songs WHERE dirty = 1
                          UNION SELECT previous FROM track_songs WHERE dirty = 1)
       ON CONFLICT(played_at_ms, track_id) DO UPDATE SET song = excluded.song, n = excluded.n
     WHERE play_numbers.song IS NOT excluded.song OR play_numbers.n IS NOT excluded.n;

UPDATE track_songs SET previous = NULL, dirty = 0 WHERE dirty = 1;
